<script setup lang="ts">
import {ref,onUnmounted} from 'vue'
import {useRouter} from 'vue-router'
import {ArrowLeft,Download,Upload} from 'lucide-vue-next'
import {useLocal} from '../stores/local'
import {exportLocalBackup,previewLocalBackup,restoreLocalBackup,type BackupPreview} from '../repositories/local-backup'
const labels:Record<string,string>={story:'故事',paragraph:'段落',source:'原文件',sourceChunk:'文件片段',card:'角色卡',session:'会话',message:'消息',companion:'伴侣',memory:'记忆',relationship:'共同记录',note:'笔记',progress:'阅读位置',task:'历史请求',settings:'设置'}
const store=useLocal(),router=useRouter(),password=ref(''),restorePassword=ref(''),includeKeys=ref(false),file=ref<File|null>(null),preview=ref<BackupPreview|null>(null),busy=ref(false),error=ref(''),status=ref('');let controller:AbortController|null=null
function select(event:Event){file.value=(event.target as HTMLInputElement).files?.[0]||null;preview.value=null;error.value=''}
async function exportBackup(){const vault=store.vault;if(!vault||busy.value)return;busy.value=true;error.value='';status.value='正在封装私人库…';controller=new AbortController();try{const bytes=await exportLocalBackup(vault,password.value,includeKeys.value,controller.signal),url=URL.createObjectURL(new Blob([Uint8Array.from(bytes)],{type:'application/octet-stream'})),link=document.createElement('a');link.href=url;link.download='故事私人库-'+new Date().toISOString().slice(0,10)+'.storyvault';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status.value='迁移包已导出';password.value=''}catch(e){error.value=(e as Error).message;status.value=''}finally{busy.value=false;controller=null}}
async function inspect(){if(!file.value||busy.value)return;busy.value=true;error.value='';preview.value=null;controller=new AbortController();try{if(file.value.size>128*1024*1024+16384)throw new Error('迁移包超过 128 MiB');preview.value=await previewLocalBackup(new Uint8Array(await file.value.arrayBuffer()),password.value,controller.signal);status.value='校验完成，原库尚未改变';password.value=''}catch(e){error.value=(e as Error).message;status.value=''}finally{busy.value=false;controller=null}}
async function restore(){if(!preview.value||busy.value)return;busy.value=true;error.value='';controller=new AbortController();try{const result=await restoreLocalBackup(preview.value,restorePassword.value,controller.signal);restorePassword.value='';preview.value=null;await store.adopt(result.vault);await router.push('/local/library')}catch(e){error.value=(e as Error).message}finally{busy.value=false;controller=null}}
onUnmounted(()=>{controller?.abort();password.value='';restorePassword.value='';preview.value=null})
</script>
<template><section><div class="final-page-heading"><RouterLink class="final-icon-button" to="/local/settings" aria-label="返回我的"><ArrowLeft :size="22"/></RouterLink><div class="final-heading-copy"><span class="final-eyebrow">TAKE YOUR STORIES</span><h1>备份与迁移</h1></div></div><p v-if="error" class="final-error" role="alert">{{error}}</p><p v-if="status" role="status">{{status}}</p><div class="final-settings"><form class="final-setting-card" @submit.prevent="exportBackup"><h2>带走私人库</h2><label>备份口令<input v-model="password" type="password" autocomplete="new-password" minlength="8" maxlength="1024" required :disabled="busy"></label><label class="final-check"><input v-model="includeKeys" type="checkbox" :disabled="busy">同时迁移供应商密钥</label><p v-if="includeKeys" class="final-subtle">密钥只放进加密包。持有文件和备份口令的人可以恢复这些密钥。</p><button class="final-primary" :disabled="busy"><Download :size="18"/>导出加密迁移包</button></form><section class="final-setting-card"><h2>在这里恢复</h2><form class="final-card-form" @submit.prevent="inspect"><label>加密迁移包<input type="file" accept=".storyvault" :disabled="busy" @change="select"></label><label>备份口令<input v-model="password" type="password" minlength="8" maxlength="1024" required :disabled="busy"></label><button :disabled="busy||!file"><Upload :size="18"/>检查迁移包</button></form><div v-if="preview"><p>{{preview.objects}} 个对象 · {{preview.revisions}} 个历史版本</p><p class="final-subtle">{{preview.includesProviderKeys?'包含已选择迁移的供应商密钥':'不包含供应商密钥'}} · 恢复到新的私人库</p><dl><template v-for="(count,kind) in preview.counts" :key="kind"><dt v-if="count">{{labels[String(kind)]||kind}}</dt><dd v-if="count">{{count}}</dd></template></dl><form class="final-card-form" @submit.prevent="restore"><label>新私人库解锁口令<input v-model="restorePassword" type="password" autocomplete="new-password" minlength="8" maxlength="1024" required :disabled="busy"></label><button class="final-primary" :disabled="busy">恢复为新私人库</button></form></div></section></div><button v-if="busy" @click="controller?.abort()">停止本次操作</button></section></template>
